CREATE TABLE IF NOT EXISTS schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE branches(id uuid PRIMARY KEY, name text NOT NULL, address text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', footer text NOT NULL DEFAULT 'Thank you for visiting.', timezone text NOT NULL DEFAULT 'Asia/Karachi', invoice_prefix text NOT NULL DEFAULT 'MAIN', tax_confirmed boolean NOT NULL DEFAULT false, tax_bps integer NOT NULL DEFAULT 0 CHECK(tax_bps BETWEEN 0 AND 10000));
CREATE TABLE users(id uuid PRIMARY KEY, branch_id uuid NOT NULL REFERENCES branches, name text NOT NULL, username text UNIQUE NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('OWNER','MANAGER','PHARMACIST','CASHIER','CLERK','ACCOUNTANT','AUDITOR')), active boolean NOT NULL DEFAULT true);
CREATE TABLE sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, csrf text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE medicines(id uuid PRIMARY KEY, branch_id uuid NOT NULL REFERENCES branches, sku text NOT NULL, barcode text NOT NULL, name text NOT NULL, generic text NOT NULL, strength text NOT NULL, form text NOT NULL, manufacturer text NOT NULL DEFAULT '', aliases text NOT NULL DEFAULT '', base_unit text NOT NULL, reorder_level integer NOT NULL DEFAULT 20 CHECK(reorder_level>=0), restricted boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true, UNIQUE(branch_id,sku), UNIQUE(barcode));
CREATE TABLE units(id uuid PRIMARY KEY, medicine_id uuid NOT NULL REFERENCES medicines, name text NOT NULL, factor integer NOT NULL CHECK(factor>0), price_paisa bigint NOT NULL CHECK(price_paisa>=0), UNIQUE(medicine_id,name));
CREATE TABLE suppliers(id uuid PRIMARY KEY, branch_id uuid NOT NULL REFERENCES branches, name text NOT NULL, phone text NOT NULL DEFAULT '');
CREATE TABLE purchases(id uuid PRIMARY KEY, branch_id uuid NOT NULL REFERENCES branches, supplier_id uuid NOT NULL REFERENCES suppliers, vendor_ref text NOT NULL, idempotency_key uuid NOT NULL, request_hash text NOT NULL, total_paisa bigint NOT NULL CHECK(total_paisa>=0), actor_id uuid NOT NULL REFERENCES users, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(branch_id,supplier_id,vendor_ref), UNIQUE(branch_id,idempotency_key));
CREATE TABLE batches(id uuid PRIMARY KEY, branch_id uuid NOT NULL REFERENCES branches, medicine_id uuid NOT NULL REFERENCES medicines, purchase_id uuid NOT NULL REFERENCES purchases, batch_code text NOT NULL, expiry date NOT NULL, quantity integer NOT NULL CHECK(quantity>=0), cost_paisa bigint NOT NULL CHECK(cost_paisa>=0), status text NOT NULL DEFAULT 'AVAILABLE' CHECK(status IN ('AVAILABLE','QUARANTINED','RECALLED','EXPIRED','DAMAGED','RETURNED','DISPOSED')), location text NOT NULL DEFAULT 'Main shelf');
CREATE INDEX batches_fefo ON batches(branch_id,medicine_id,expiry,status);
CREATE TABLE purchase_lines(id uuid PRIMARY KEY, purchase_id uuid NOT NULL REFERENCES purchases, batch_id uuid NOT NULL REFERENCES batches, unit_id uuid NOT NULL REFERENCES units, quantity integer NOT NULL CHECK(quantity>0), quantity_base integer NOT NULL CHECK(quantity_base>0), unit_cost_paisa bigint NOT NULL CHECK(unit_cost_paisa>=0));
CREATE TABLE sales(id uuid PRIMARY KEY, branch_id uuid NOT NULL REFERENCES branches, number text NOT NULL, idempotency_key uuid NOT NULL, request_hash text NOT NULL, actor_id uuid NOT NULL REFERENCES users, subtotal_paisa bigint NOT NULL, discount_paisa bigint NOT NULL, tax_paisa bigint NOT NULL, total_paisa bigint NOT NULL, change_paisa bigint NOT NULL, notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(branch_id,number), UNIQUE(branch_id,idempotency_key));
CREATE SEQUENCE invoice_sequence;
CREATE TABLE sale_lines(id uuid PRIMARY KEY, sale_id uuid NOT NULL REFERENCES sales, medicine_id uuid NOT NULL REFERENCES medicines, medicine_name text NOT NULL, description text NOT NULL, unit_name text NOT NULL, factor integer NOT NULL, quantity integer NOT NULL CHECK(quantity>0), price_paisa bigint NOT NULL, cost_paisa bigint NOT NULL, total_paisa bigint NOT NULL);
CREATE TABLE allocations(id uuid PRIMARY KEY, line_id uuid NOT NULL REFERENCES sale_lines, batch_id uuid NOT NULL REFERENCES batches, batch_code text NOT NULL, expiry date NOT NULL, quantity_base integer NOT NULL CHECK(quantity_base>0), cost_paisa bigint NOT NULL);
CREATE TABLE payments(id uuid PRIMARY KEY, sale_id uuid NOT NULL REFERENCES sales, method text NOT NULL CHECK(method IN ('CASH','CARD','WALLET')), amount_paisa bigint NOT NULL CHECK(amount_paisa>0), reference text NOT NULL DEFAULT '');
CREATE TABLE movements(id uuid PRIMARY KEY, branch_id uuid NOT NULL REFERENCES branches, batch_id uuid NOT NULL REFERENCES batches, quantity_base integer NOT NULL CHECK(quantity_base<>0), type text NOT NULL CHECK(type IN ('RECEIPT','SALE')), reference_id uuid NOT NULL, actor_id uuid NOT NULL REFERENCES users, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE supplier_entries(id uuid PRIMARY KEY, branch_id uuid NOT NULL REFERENCES branches, supplier_id uuid NOT NULL REFERENCES suppliers, purchase_id uuid NOT NULL REFERENCES purchases, amount_paisa bigint NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events(id uuid PRIMARY KEY, branch_id uuid REFERENCES branches, actor_id uuid REFERENCES users, action text NOT NULL, entity_id text NOT NULL, details jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sales_branch_date ON sales(branch_id,created_at);
CREATE INDEX movements_batch_date ON movements(batch_id,created_at);
CREATE FUNCTION deny_history_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Posted history is append-only'; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['sales','sale_lines','allocations','payments','purchases','purchase_lines','movements','supplier_entries','audit_events'] LOOP EXECUTE format('CREATE TRIGGER immutable_history BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION deny_history_change()',t); END LOOP; END $$;
